def serif_fonts():
    """Use local Times New Roman fonts when present, otherwise PDF Times."""
    directories = (
        Path('/System/Library/Fonts/Supplemental'),
        Path('/Library/Fonts'),
        Path(os.environ.get('WINDIR', 'C:/Windows')) / 'Fonts',
    )
    for directory in directories:
        for regular, bold in (('Times New Roman.ttf', 'Times New Roman Bold.ttf'),
                              ('times.ttf', 'timesbd.ttf')):
            regular, bold = directory / regular, directory / bold
            if regular.is_file() and bold.is_file():
                pdfmetrics.registerFont(TTFont('TimesNewRoman', str(regular)))
                pdfmetrics.registerFont(TTFont('TimesNewRoman-Bold', str(bold)))
                return 'TimesNewRoman', 'TimesNewRoman-Bold'
    return 'Times-Roman', 'Times-Bold'


def main(payload=None, output=OUTPUT):
    map_pdf = zlib.decompress(base64.b64decode(_MAP_ASSET))
    regular_font, bold_font = serif_fonts()
    row = RECORDED_RESULT if payload is None else payload['mission_result']
    mission = MISSION if payload is None else payload['mission_geometry']
    if payload is not None:
        # The pre-authored background is valid for this published layout.
        if len(mission['tasks']) != len(MISSION['tasks']):
            raise ValueError('Replay geometry does not match the embedded map.')
        expected = {int(item['idx']): item for item in MISSION['tasks']}
        for task in mission['tasks']:
            original = expected[int(task['idx'])]
            if not all(math.isclose(float(task[key]), original[key], abs_tol=1e-10, rel_tol=0.0) for key in ('lon', 'lat')):
                raise ValueError('Replay geometry does not match the embedded map.')
    output = Path(output)
    output.parent.mkdir(parents=True, exist_ok=True)
    route = [int(n) for n in row['route'].split('-')]
    seed = int(row['seed'])
    wcr = float(row['weighted_completed']) / float(row['total_weight'])
    completed = int(row['completed_tasks'])
    visited = int(row['visited_tasks'])
    skipped = int(row['skipped_tasks'])
    assert route[0] == route[-1] == 0
    assert len(route[1:-1]) == len(set(route[1:-1])) == visited
    assert completed + skipped == visited
    assert int(row['local_actions']) + int(row['mec_actions']) == completed
    assert abs(wcr - float(row['mcr'])) < 1e-12
    assert int(row['return_success']) == 1
    assert float(row['final_time_s']) <= float(row['t_max_s'])
    assert float(row['final_energy_kj']) <= float(row['e_max_kj'])

    coords = {0: (mission['base']['lon'], mission['base']['lat'])}
    coords.update({int(t['idx']): (t['lon'], t['lat']) for t in mission['tasks']})
    LON_MIN, LON_MAX = 113.515, 113.610
    LAT_MIN, LAT_MAX = 22.095, 22.225
    with pdfplumber.open(BytesIO(map_pdf)) as pdf:
        p = pdf.pages[0]
        # The largest non-page rectangle is the main axes background.
        axes = max((r for r in p.rects if r['x0'] > 1), key=lambda r: r['width'] * r['height'])
        X0, X1, Y0, Y1 = axes['x0'], axes['x1'], axes['y0'], axes['y1']
        width, height = p.width, p.height
        words = p.extract_words()


    def project(lon, lat):
        return (X0 + (lon-LON_MIN)/(LON_MAX-LON_MIN)*(X1-X0),
                Y0 + (lat-LAT_MIN)/(LAT_MAX-LAT_MIN)*(Y1-Y0))


    def xy(node):
        return project(*coords[node])


    # Protect the original markers and labels. The real straight flight segments
    # are only visually interrupted behind these foreground objects.
    obstacles = []
    for i in coords:
        x, y = xy(i)
        r = 9 if i == 0 else 7.8
        obstacles.append((x-r, y-r, x+r, y+r))
    for m in mission['mec']:
        x, y = project(m['lon'], m['lat'])
        obstacles.append((x-8, y-8, x+8, y+8))
    for w in words:
        obstacles.append((w['x0']-1.0, height-w['bottom']-1.0,
                          w['x1']+1.0, height-w['top']+1.0))


    def interval_in_box(a, b, rect):
        """Parameter interval where segment a + u(b-a) meets an axis-aligned box."""
        lo, hi = 0.0, 1.0
        for j, (rmin, rmax) in enumerate(((rect[0], rect[2]), (rect[1], rect[3]))):
            delta = b[j] - a[j]
            if abs(delta) < 1e-12:
                if not rmin <= a[j] <= rmax:
                    return None
            else:
                u, v = sorted(((rmin-a[j])/delta, (rmax-a[j])/delta))
                lo, hi = max(lo, u), min(hi, v)
                if hi <= lo:
                    return None
        return lo, hi


    def visible_intervals(a, b):
        blocks = sorted(i for r in obstacles if (i := interval_in_box(a, b, r)))
        parts, last = [], 0.0
        for lo, hi in blocks:
            if lo > last:
                parts.append((last, lo))
            last = max(last, hi)
        if last < 1:
            parts.append((last, 1))
        return parts


    buf = BytesIO()
    c = canvas.Canvas(buf, pagesize=(width, height))
    c.setFont(regular_font, 1)
    navy = HexColor('#173F67')
    muted = HexColor('#52616F')
    points = [xy(n) for n in route]
    segments = list(zip(points[:-1], points[1:]))

    for a, b in segments:
        length = math.dist(a, b)
        for lo, hi in visible_intervals(a, b):
            if (hi-lo)*length < 1:
                continue
            start = (a[0] + lo*(b[0]-a[0]), a[1] + lo*(b[1]-a[1]))
            end = (a[0] + hi*(b[0]-a[0]), a[1] + hi*(b[1]-a[1]))
            c.saveState()
            c.setLineCap(0)
            c.setStrokeColor(navy)
            c.setLineWidth(1.8)
            c.setDash([6, 4], phase=(lo*length) % 10)
            c.line(*start, *end)
            c.restoreState()


    def open_arrow(x, y, theta, size, color, linewidth):
        """Draw an open two-line arrowhead at (x, y)."""
        back = theta + math.pi
        spread = 0.52
        p1 = (x + size*math.cos(back-spread), y + size*math.sin(back-spread))
        p2 = (x + size*math.cos(back+spread), y + size*math.sin(back+spread))
        c.saveState()
        c.setStrokeColor(color)
        c.setLineWidth(linewidth)
        c.setLineCap(1)
        c.line(x, y, *p1)
        c.line(x, y, *p2)
        c.restoreState()


    def segment_distance(p, a, b):
        dx,dy = b[0]-a[0], b[1]-a[1]
        u = max(0, min(1, ((p[0]-a[0])*dx+(p[1]-a[1])*dy)/(dx*dx+dy*dy)))
        return math.dist(p, (a[0]+u*dx,a[1]+u*dy))


    for idx, (a,b) in enumerate(segments):
        if idx == 0:
            continue
        # Place an arrow away from labels and the crossing of outbound/return legs.
        candidates = []
        for frac in [.50, .38, .62, .28, .72, .20, .80]:
            p = (a[0]+frac*(b[0]-a[0]), a[1]+frac*(b[1]-a[1]))
            blocked = any(r[0]-6 < p[0] < r[2]+6 and r[1]-6 < p[1] < r[3]+6 for r in obstacles)
            if not blocked:
                clearance = min(segment_distance(p, d, e) for j,(d,e) in enumerate(segments) if j != idx)
                candidates.append((min(clearance,20) - abs(frac-.5), p))
        if candidates:
            p = max(candidates, key=lambda v: v[0])[1]
            theta = math.atan2(b[1]-a[1], b[0]-a[0])
            open_arrow(*p, theta, 7.4, navy, 2.4)

    # Keep the departure direction visible immediately after the base marker.
    a, b = segments[0]
    p = (a[0] + 0.48*(b[0]-a[0]), a[1] + 0.48*(b[1]-a[1]))
    theta = math.atan2(b[1]-a[1], b[0]-a[0])
    open_arrow(*p, theta, 7.4, navy, 2.4)

    # Tasks reached by the UAV but skipped after workload revelation.
    skipped_nodes = ({8, 19} if payload is None else
                     {int(event['task']) for event in payload['trace']
                      if event['mode'] == 'skip'})
    skip_color = HexColor('#6B7280')
    for task_id in skipped_nodes:
        x, y = xy(task_id)
        c.saveState()
        c.setFillColor(skip_color)
        c.setFont(bold_font, 9.0)
        c.drawString(x+9, y-2.5, 'skip')
        c.restoreState()

    # Keep the result box compact and free of route annotations.
    rx, ry, rw, rh = 96, 218, 121, 95
    c.setFillColor(white)
    c.setFillAlpha(0.95)
    c.setStrokeColor(HexColor('#595959'))
    c.setLineWidth(1)
    c.roundRect(rx,ry,rw,rh,5,stroke=1,fill=1)
    c.setFillAlpha(1.0)
    c.setFillColor(navy)
    c.setFont(bold_font,13.0)
    c.drawString(rx+8,ry+rh-20,f'WCR = {100*wcr:.1f}%')

    # Draw each item as one continuous line so labels and values remain visually grouped.
    left_x = rx + 8
    lines = [
        f'Weight: {float(row["weighted_completed"]):g} / {float(row["total_weight"]):g}',
        f'Tasks: {completed} / {int(row["n_tasks"])}',
        f'Visited: {visited}; skipped: {skipped}',
        f'Time: {float(row["final_time_s"]):.1f} / {float(row["t_max_s"]):.0f} s',
        f'Energy: {float(row["final_energy_kj"]):.1f} / {float(row["e_max_kj"]):.0f} kJ',
    ]
    for j, line in enumerate(lines):
        baseline = ry + rh - 38 - j * 11.5
        c.setFont(regular_font, 8.8 if j < 2 else 8.2)
        c.drawString(left_x, baseline, line)

    c.showPage()
    c.save()
    buf.seek(0)
    reader = PdfReader(BytesIO(map_pdf))
    page = reader.pages[0]
    page.merge_page(PdfReader(buf).pages[0])
    # ReportLab reserves a default Helvetica resource even when no Helvetica text
    # is drawn. Remove that unused initialization from the merged content so that
    # the final PDF contains only the map fonts and the embedded Times New Roman
    # overlay fonts.
    content = page.get_contents().get_data()
    content = content.replace(b'/F1-0 12 Tf\n14.4 TL\nET\n', b'')
    page[NameObject('/Contents')] = DecodedStreamObject()
    page[NameObject('/Contents')].set_data(content)
    fonts = page['/Resources'].get('/Font')
    if fonts is not None and '/F1-0' in fonts:
        del fonts['/F1-0']
    writer = PdfWriter()
    writer.add_page(page)
    writer.pages[0].compress_content_streams()
    writer.add_metadata({'/Title':'Proposed UAV route in the Macau simulation scenario',
                         '/Subject':f'Formal nominal mission, seed {seed}; full round trip and observed outcome'})
    with output.open('wb') as f:
        writer.write(f)



